/**
 * The boot mark: the apple silhouette the original showed here.
 *
 * Built from geometry rather than traced. The body is the union of two
 * lobe ellipses — which is what produces the twin hump and the notch
 * between them for free — plus a belly ellipse that rounds the bottom
 * without filling that notch back in. The bite is one circle subtracted
 * from the upper right. The leaf is a lens of two quadratic curves, so
 * both ends come to a point, rotated 50 degrees out of the notch.
 *
 * Generated by a script rather than drawn by hand, so the parameters are
 * recoverable: lobes at (72,128) and (140,124) with radii 50x74, belly
 * at (106,142) radii 76x62, bite circle at (200,100) radius 36, leaf 62
 * long and 26 wide based at (108,66).
 *
 * Stored at RASTER resolution (167 x 185), not logical.
 *
 * That is the whole reason the edges are smooth. The panel is 176x132
 * logical at scale 2, so a mark stored at logical size has every one of
 * its pixels blown up into a 2x2 block, and every curve stair-steps in
 * chunks twice as coarse as the screen can actually show. Storing it at
 * device resolution and blitting 1:1 halves the step, at the cost of 4x
 * the data — a few KB of base64, which is nothing.
 */

/** Dimensions in RASTER pixels — divide by the LCD scale for logical. */
export const MARK_W = 167;
export const MARK_H = 185;

const PACKED =
  'AAAAAAAAAAAAAAAAAAAAPAAAAAAAAAAAAAAAAAAAAAAAAAAH+AAAAAAAAAAAAAAAAAAAAAAAAAD/' +
  '8AAAAAAAAAAAAAAAAAAAAAAAAAf/4AAAAAAAAAAAAAAAAAAAAAAAAD//wAAAAAAAAAAAAAAAAAAA' +
  'AAAAAf//AAAAAAAAAAAAAAAAAAAAAAAAD//+AAAAAAAAAAAAAAAAAAAAAAAAP//8AAAAAAAAAAAA' +
  'AAAAAAAAAAAB///4AAAAAAAAAAAAAAAAAAAAAAAH///wAAAAAAAAAAAAAAAAAAAAAAAf///gAAAA' +
  'AAAAAAAAAAAAAAAAAAB////AAAAAAAAAAAAAAAAAAAAAAAH///8AAAAAAAAAAAAAAAAAAAAAAA//' +
  '//4AAAAAAAAAAAAAAAAAAAAAAD////wAAAAAAAAAAAAAAAAAAAAAAH////gAAAAAAAAAAAAAAAAA' +
  'AAAAAf////AAAAAAAAAAAAAAAAAAAAAAB////8AAAAAAAAAAAAAAAAAAAAAAH////4AAAAAAAAAA' +
  'AAAAAAAAAAAAP////wAAAAAAAAAAAAAAAAAAAAAA/////AAAAAAAAAAAAAAAAAAAAAAB////+AAA' +
  'AAAAAAAAAAAAAAAAAAAH////4AAAAAAAAAAAAAAAAAAAAAAP////wAAAAAAAAAAAAAAAAAAAAAA/' +
  '////gAAAAAAAAAAAAAAAAAAAAAB////+AAAAAAAAAAAAAAAAAAAAAAH////4AAAAAAAAAAAAAAAA' +
  'AAAAAAP////wAAAAAAAAAAAAAAAAAAAAAAf////AAAAAAAAAAAAAAAAAAAAAAB////8AAAAAAAAA' +
  'AAAAAAAAAAAAAD////4AAAAAAAAAAAAAAAAAAAAAAH/////4AAAAAAAAAAAAAAAAAAAAAP//////' +
  'AAAAAAAAAAAAAAAAAAAAA///////gAAAAAAAAAAAAAAAAAAAB///////4AAAAAAAAAAAAH/4AAAA' +
  'D///////8AAAAAAAAAAAD///AAAAH///////+AAAAAAAAAAAf///gAAAP///////+AAAAAAAAAAH' +
  '////4AAAf////////AAAAAAAAAA/////8AAA/////////AAAAAAAAAH/////+AAD/////////AAA' +
  'AAAAAAf/////+AAH/////////AAAAAAAAD///////AAP/////////gAAAAAAAP///////AAf////' +
  '/////gAAAAAAA////////AA//////////gAAAAAAH////////AB//////////gAAAAAAf///////' +
  '/gD//////////AAAAAAB/////////gD//////////AAAAAAH/////////gP//////////AAAAAAf' +
  '/////////g///////////AAAAAB//////////D///////////AAAAAD//////////H//////////' +
  '+AAAAAP//////////f//////////+AAAAA//////////////////////+AAAAD//////////////' +
  '////////8AAAAH//////////////////////wAAAAf//////////////////////AAAAB///////' +
  '///////////////8AAAAD//////////////////////wAAAAP//////////////////////AAAAA' +
  '//////////////////////8AAAAB//////////////////////4AAAAH////////////////////' +
  '//gAAAAP//////////////////////AAAAA//////////////////////8AAAAB/////////////' +
  '/////////4AAAAH//////////////////////gAAAAP//////////////////////AAAAA//////' +
  '////////////////8AAAAB//////////////////////4AAAAH//////////////////////wAAA' +
  'AP//////////////////////AAAAAf/////////////////////+AAAAB///////////////////' +
  '///8AAAAD//////////////////////4AAAAP//////////////////////wAAAAf///////////' +
  '///////////AAAAA//////////////////////+AAAAB//////////////////////8AAAAH////' +
  '//////////////////4AAAAP//////////////////////wAAAAf//////////////////////gA' +
  'AAB///////////////////////AAAAD//////////////////////+AAAAH/////////////////' +
  '/////8AAAAP//////////////////////4AAAA///////////////////////4AAAB//////////' +
  '/////////////wAAAD///////////////////////gAAAH///////////////////////AAAAP//' +
  '////////////////////+AAAA///////////////////////+AAAB///////////////////////' +
  '8AAAD///////////////////////4AAAH///////////////////////4AAAP///////////////' +
  '////////wAAAf///////////////////////wAAA////////////////////////gAAB////////' +
  '////////////////gAAH////////////////////////AAAP////////////////////////AAAf' +
  '///////////////////////+AAA////////////////////////+AAB/////////////////////' +
  '///+AAD////////////////////////+AAH////////////////////////+AAP/////////////' +
  '///////////+AAf////////////////////////+AA/////////////////////////+AB//////' +
  '///////////////////+AD/////////////////////////+AH//////////////////////////' +
  'AP//////////////////////////gf//////////////////////////w///////////////////' +
  '////////5///////////////////////////////////////////////////////////////////' +
  '////////////////////////////////////////////v///////////////////////////f///' +
  '///////////////////////+///////////////////////////9////////////////////////' +
  '///7///////////////////////////n///////////////////////////P////////////////' +
  '//////////+f//////////////////////////8f//////////////////////////4/////////' +
  '//////////////////h///////////////////////////D//////////////////////////+H/' +
  '/////////////////////////8H//////////////////////////wP/////////////////////' +
  '/////gf//////////////////////////A//////////////////////////8A//////////////' +
  '////////////4B//////////////////////////wD//////////////////////////gD//////' +
  '///////////////////+AH/////////////////////////8AP/////////////////////////w' +
  'Af/////////////////////////gAf/////////////////////////AA///////////////////' +
  '//////8AA/////////////////////////4AB/////////////////////////gAD///////////' +
  '//////////////AAD////////////////////////8AAH////////////////////////4AAH///' +
  '/////////////////////gAAP////////////////////////AAAP///////////////////////' +
  '8AAAf///////////////////////4AAAf///////////////////////gAAA////////////////' +
  '///////+AAAA///////////////////////8AAAB///////////////////////wAAAB////////' +
  '///////////////AAAAB//////////////////////+AAAAD//////////////////////4AAAAD' +
  '//////////////////////gAAAAD/////////////////////+AAAAAH////////////////////' +
  '/4AAAAAH/////////////////////wAAAAAH/////////////////////AAAAAAH////////////' +
  '////////8AAAAAAH////////////////////wAAAAAAP///////////////////+AAAAAAAP////' +
  '///////////////4AAAAAAAP///////////////////gAAAAAAAP//////////////////+AAAAA' +
  'AAAH//////////////////wAAAAAAAAH//////////////////AAAAAAAAAH////////////////' +
  '/4AAAAAAAAAH/////////////////AAAAAAAAAAD////////////////4AAAAAAAAAAD////////' +
  '///////+AAAAAAAAAAAB//////////////+AAAAAAAAAAAAA/////////////wAAAAAAAAAAAAAA' +
  'f///////////8AAAAAAAAAAAAAAAH///////////AAAAAAAAAAAAAAAAAf+Af//////gAAAAAAAA' +
  'AAAAAAAAAAAAB/////gAAAAAAAAAAAAAAAAAAAAAAB//+AAAAAAAAAAAAA==';

let unpacked: Uint8Array | null = null;

/** Lazily expand the packed rows to one byte per pixel. */
export function markBits(): Uint8Array {
  if (unpacked) return unpacked;
  const bin = atob(PACKED);
  const out = new Uint8Array(MARK_W * MARK_H);
  for (let i = 0; i < out.length; i++) {
    out[i] = (bin.charCodeAt(i >> 3) >> (7 - (i & 7))) & 1;
  }
  unpacked = out;
  return out;
}
